e(self, value: int | None) -> None:\n   742\t        if value is not None and value <= 0:\n   743\t            raise ValueError(\"maxsize must be None or a non-negative integer.\")\n   744\t        self._maxsize = value\n   745\t        if value is not None:\n   746\t            while len(self._cache) > value:\n   747\t                self._cache.popitem(False)\n   748\t\n   749\t    def get(self, n: int, default=None):\n   750\t        \"\"\" Return the prime factor of ``n``.\n   751\t        If it does not exist in the cache, return the value of ``default``.\n   752\t        \"\"\"\n   753\t        if n <= sieve._list[-1]:\n   754\t            if sieve._list[bisect_left(sieve._list, n)] == n:\n   755\t                return n\n   756\t        if n in self._cache:\n   757\t            self._cache.move_to_end(n)\n   758\t            return self._cache[n]\n   759\t        if factors := self.get_external(n):\n   760\t            self.add(n, factors)\n   761\t            return self._cache[n]\n   762\t        return default\n   763\t\n   764\t    def add(self, n: int, factors: list[int]) -> None:\n   765\t        for p in sorted(factors, reverse=True):\n   766\t            self[n] = p\n   767\t            n, _ = remove(n, p)\n   768\t\n   769\t    def get_external(self, n: int) -> list[int] | None:\n   770\t        return None\n   771\t\n   772\t\n   773\tfactor_cache = FactorCache(maxsize=1000)\n   774\t\n   775\t\n   776\tdef pollard_rho(n, s=2, a=1, retries=5, seed=1234, max_steps=None, F=None):\n   777\t    r\"\"\"\n   778\t    Use Pollard's rho method to try to extract a nontrivial factor\n   779\t    of ``n``. The returned factor may be a composite number. If no\n   780\t    factor is found, ``None`` is returned.\n   781\t\n   782\t    The algorithm generates pseudo-random values of x with a generator\n   783\t    function, replacing x with F(x). If F is not supplied then the\n   784\t    function x**2 + ``a`` is used. The first value supplied to F(x) is ``s``.\n   785\t    Upon failure (if ``retries`` is > 0) a new ``a`` and ``s`` will be\n   786\t    supplied; the ``a`` will be ignored if F was supplied.\n   787\t\n   788\t    The sequence of numbers generated by such functions generally have a\n   789\t    a lead-up to some number and then loop around back to that number and\n   790\t    begin to repeat the sequence, e.g. 1, 2, 3, 4, 5, 3, 4, 5 -- this leader\n   791\t    and loop look a bit like the Greek letter rho, and thus the name, 'rho'.\n   792\t\n   793\t    For a given function, very different leader-loop values can be obtained\n   794\t    so it is a good idea to allow for retries:\n   795\t\n   796\t    >>> from sympy.ntheory.generate import cycle_length\n   797\t    >>> n = 16843009\n   798\t    >>> F = lambda x:(2048*pow(x, 2, n) + 32767) % n\n   799\t    >>> for s in range(5):\n   800\t    ...     print('loop length = %4i; leader length = %3i' % next(cycle_length(F, s)))\n   801\t    ...\n   802\t    loop length = 2489; leader length =  43\n   803\t    loop length =   78; leader length = 121\n   804\t    loop length = 1482; leader length = 100\n   805\t    loop length = 1482; leader length = 286\n   806\t    loop length = 1482; leader length = 101\n   807\t\n   808\t    Here is an explicit example where there is a three element leadup to\n   809\t    a sequence of 3 numbers (11, 14, 4) that then repeat:\n   810\t\n   811\t    >>> x=2\n   812\t    >>> for i in range(9):\n   813\t    ...     print(x)\n   814\t    ...     x=(x**2+12)%17\n   815\t    ...\n   816\t    2\n   817\t    16\n   818\t    13\n   819\t    11\n   820\t    14\n   821\t    4\n   822\t    11\n   823\t    14\n   824\t    4\n   825\t    >>> next(cycle_length(lambda x: (x**2+12)%17, 2))\n   826\t    (3, 3)\n   827\t    >>> list(cycle_length(lambda x: (x**2+12)%17, 2, values=True))\n   828\t    [2, 16, 13, 11, 14, 4]\n   829\t\n   830\t    Instead of checking the differences of all generated values for a gcd\n   831\t    with n, only the kth and 2*kth numbers are checked, e.g. 1st and 2nd,\n   832\t    2nd and 4th, 3rd and 6th until it has been detected that the loop has been\n   833\t    traversed. Loops may be many thousands of steps long before rho finds a\n   834\t    factor or reports failure. If ``max_steps`` is specified, the iteration\n   835\t    is cancelled with a failure after the specified number of steps.\n   836\t\n   837\t    Examples\n   838\t    ========\n   839\t\n   840\t    >>> from sympy import pollard_rho\n   841\t    >>> n=16843009\n   842\t    >>> F=lambda x:(2048*pow(x,2,n) + 32767) % n\n   843\t    >>> pollard_rho(n, F=F)\n   844\t    257\n   845\t\n   846\t    Use the default setting with a bad value of ``a`` and no retries:\n   847\t\n   848\t    >>> pollard_rho(n, a=n-2, retries=0)\n   849\t\n   850\t    If retries is > 0 then perhaps the problem will correct itself when\n   851\t    new values are generated for a:\n   852\t\n   853\t    >>> pollard_rho(n, a=n-2, retries=1)\n   854\t    257\n   855\t\n   856\t    References\n   857\t    ==========\n   858\t\n   859\t    .. [1] Richard Crandall & Carl Pomerance (2005), \"Prime Numbers:\n   860\t           A Computational Perspective\", Springer, 2nd edition, 229-231\n   861\t\n   862\t    \"\"\"\n   863\t    n = int(n)\n   864\t    if n < 5:\n   865\t        raise ValueError('pollard_rho should receive n > 4')\n   866\t    randint = _randint(seed + retries)\n   867\t    V = s\n   868\t    for i in range(retries + 1):\n   869\t        U = V\n   870\t        if not F:\n   871\t            F = lambda x: (pow(x, 2, n) + a) % n\n   872\t        j = 0\n   873\t        while 1:\n   874\t            if max_steps and (j > max_steps):\n   875\t                break\n   876\t            j += 1\n   877\t            U = F(U)\n   878\t            V = F(F(V))  # V is 2x further along than U\n   879\t            g = gcd(U - V, n)\n   880\t            if g == 1:\n   881\t                continue\n   882\t            if g == n:\n   883\t                break\n   884\t            return int(g)\n   885\t        V = randint(0, n - 1)\n   886\t        a = randint(1, n - 3)  # for x**2 + a, a%n should not be 0 or -2\n   887\t        F = None\n   888\t    return None\n   889\t\n   890\t\n   891\tdef pollard_pm1(n, B=10, a=2, retries=0, seed=1234):\n   892\t    \"\"\"\n   893\t    Use Pollard's p-1 method to try to extract a nontrivial factor\n   894\t    of ``n``. Either a divisor (perhaps composite) or ``None`` is returned.\n   895\t\n   896\t    The value of ``a`` is the base that is used in the test gcd(a**M - 1, n).\n   897\t    The default is 2.  If ``retries`` > 0 then if no factor is found after the\n   898\t    first attempt, a new ``a`` will be generated randomly (using the ``seed``)\n   899\t    and the process repeated.\n   900\t\n   901\t    Note: the value of M is lcm(1..B) = reduce(ilcm, range(2, B + 1)).\n   902\t\n   903\t    A search is made for factors next to even numbers having a power smoothness\n   904\t    less than ``B``. Choosing a larger B increases the likelihood of finding a\n   905\t    larger factor but takes longer. Whether a factor of n is found or not\n   906\t    depends on ``a`` and the power smoothness of the even number just less than\n   907\t    the factor p (hence the name p - 1).\n   908\t\n   909\t    Although some discussion of what constitutes a good ``a`` some\n   910\t    descriptions are hard to interpret. At the modular.math site referenced\n   911\t    below it is stated that if gcd(a**M - 1, n) = N then a**M % q**r is 1\n   912\t    for every prime power divisor of N. But consider the following:\n   913\t\n   914\t        >>> from sympy.ntheory.factor_ import smoothness_p, pollard_pm1\n   915\t        >>> n=257*1009\n   916\t        >>> smoothness_p(n)\n   917\t        (-1, [(257, (1, 2, 256)), (1009, (1, 7, 16))])\n   918\t\n   919\t    So we should (and can) find a root with B=16:\n   920\t\n   921\t        >>> pollard_pm1(n, B=16, a=3)\n   922\t        1009\n   923\t\n   924\t    If we attempt to increase B to 256 we find that it does not work:\n   925\t\n   926\t        >>> pollard_pm1(n, B=256)\n   927\t        >>>\n   928\t\n   929\t    But if the value of ``a`` is changed we find that only multiples of\n   930\t    257 work, e.g.:\n   931\t\n   932\t        >>> pollard_pm1(n, B=256, a=257)\n   933\t        1009\n   934\t\n   935\t    Checking different ``a`` values shows that all the ones that did not\n   936\t    work had a gcd value not equal to ``n`` but equal to one of the\n   937\t    factors:\n   938\t\n   939\t        >>> from sympy import ilcm, igcd, factorint, Pow\n   940\t        >>> M = 1\n   941\t        >>> for i in range(2, 256):\n   942\t        ...     M = ilcm(M, i)\n   943\t        ...\n   944\t        >>> set([igcd(pow(a, M, n) - 1, n) for a in range(2, 256) if\n   945\t        ...      igcd(pow(a, M, n) - 1, n) != n])\n   946\t        {1009}\n   947\t\n   948\t    But does aM % d for every divisor of n give 1?\n   949\t\n   950\t        >>> aM = pow(255, M, n)\n   951\t        >>> [(d, aM%Pow(*d.args)) for d in factorint(n, visual=True).args]\n   952\t        [(257**1, 1), (1009**1, 1)]\n   953\t\n   954\t    No, only one of them. So perhaps the principle is that a root will\n   955\t    be found for a given value of B provided that:\n   956\t\n   957\t    1) the power smoothness of the p - 1 value next to the root\n   958\t       does not exceed B\n   959\t    2) a**M % p != 1 for any of the divisors of n.\n   960\t\n   961\t    By trying more than one ``a`` it is possible that one of them\n   962\t    will yield a factor.\n   963\t\n   964\t    Examples\n   965\t    ========\n   966\t\n   967\t    With the default smoothness bound, this number cannot be cracked:\n   968\t\n   969\t        >>> from sympy.ntheory import pollard_pm1\n   970\t        >>> pollard_pm1(21477639576571)\n   971\t\n   972\t    Increasing the smoothness bound helps:\n   973\t\n   974\t        >>> pollard_pm1(21477639576571, B=2000)\n   975\t        4410317\n   976\t\n   977\t    Looking at the smoothness of the factors of this number we find:\n   978\t\n   979\t        >>> from sympy.ntheory.factor_ import smoothness_p, factorint\n   980\t        >>> print(smoothness_p(21477639576571, visual=1))\n   981\t        p**i=4410317**1 has p-1 B=1787, B-pow=1787\n   982\t        p**i=4869863**1 has p-1 B=2434931, B-pow=2434931\n   983\t\n   984\t    The B and B-pow are the same for the p - 1 factorizations of the divisors\n   985\t    because those factorizations had a very large prime factor:\n   986\t\n   987\t        >>> factorint(4410317 - 1)\n   988\t        {2: 2, 617: 1, 1787: 1}\n   989\t        >>> factorint(4869863-1)\n   990\t        {2: 1, 2434931: 1}\n   991\t\n   992\t    Note that until B reaches the B-pow value of 1787, the number is not cracked;\n   993\t\n   994\t        >>> pollard_pm1(21477639576571, B=1786)\n   995\t        >>> pollard_pm1(21477639576571, B=1787)\n   996\t        4410317\n   997\t\n   998\t    The B value has to do with the factors of the number next to the divisor,\n   999\t    not the divisors themselves. A worst case scenario is that the number next\n  1000\t    to the factor p has a large prime divisisor or is a perfect power. If these\n  1001\t    conditions apply then the power-smoothness will be about p/2 or p. The more\n  1002\t    realistic is that there will be a large prime factor next to p requiring\n  1003\t    a B value on the order of p/2. Although primes may have been searched for\n  1004\t    up to this level, the p/2 is a factor of p - 1, something that we do not\n  1005\t    know. The modular.math reference below states that 15% of numbers in the\n  1006\t    range of 10**15 to 15**15 + 10**4 are 10**6 power smooth so a B of 10**6\n  1007\t    will fail 85% of the time in that range. From 10**8 to 10**8 + 10**3 the\n  1008\t    percentages are nearly reversed...but in that range the simple trial\n  1009\t    division is quite fast.\n  1010\t\n  1011\t    References\n  1012\t    ==========\n  1013\t\n  1014\t    .. [1] Richard Crandall & Carl Pomerance (2005), \"Prime Numbers:\n  1015\t           A Computational Perspective\", Springer, 2nd edition, 236-238\n  1016\t    .. [2] https://web.archive.org/web/20150716201437/http://modular.math.washington.edu/edu/2007/spring/ent/ent-html/node81.html\n  1017\t    .. [3] https://www.cs.toronto.edu/~yuvalf/Factorization.pdf\n  1018\t    \"\"\"\n  1019\t\n  1020\t    n = int(n)\n  1021\t    if n < 4 or B < 3:\n  1022\t        raise ValueError('pollard_pm1 should receive n > 3 and B > 2')\n  1023\t    randint = _randint(seed + B)\n  1024\t\n  1025\t    # computing a**lcm(1,2,3,..B) % n for B > 2\n  1026\t    # it looks weird, but it's right: primes run [2, B]\n  1027\t    # and the answer's not right until the loop is done.\n  1028\t    for i in range(retries + 1):\n  1029\t        aM = a\n  1030\t        for p in sieve.primerange(2, B + 1):\n  1031\t            e = int(math.log(B, p))\n  1032\t            aM = pow(aM, pow(p, e), n)\n  1033\t        g = gcd(aM - 1, n)\n  1034\t        if 1 < g < n:\n  1035\t            return int(g)\n  1036\t\n  1037\t        # get a new a:\n  1038\t        # since the exponent, lcm(1..B), is even, if we allow 'a' to be 'n-1'\n  1039\t        # then (n - 1)**even % n will be 1 which will give a g of 0 and 1 will\n  1040\t        # give a zero, too, so we set the range as [2, n-2]. Some references\n  1041\t        # say 'a' should be coprime to n, but either will detect factors.\n  1042\t        a = randint(2, n - 2)\n  1043\t\n  1044\t\n  1045\tdef _trial(factors, n, candidates, verbose=False):\n  1046\t    \"\"\"\n  1047\t    Helper function for integer factorization. Trial factors ``n`\n  1048\t    against all integers given in the sequence ``candidates``\n  1049\t    and updates the dict ``factors`` in-place. Returns the reduced\n  1050\t    value of ``n`` and a flag indicating whether any factors were found.\n  1051\t    \"\"\"\n  1052\t    if verbose:\n  1053\t        factors0 = list(factors.keys())\n  1054\t    nfactors = len(factors)\n  1055\t    for d in candidates:\n  1056\t        if n % d == 0:\n  1057\t            if n != d:\n  1058\t                factor_cache[n] = d\n  1059\t            n, m = remove(n // d, d)\n  1060\t            factors[d] = m + 1\n  1061\t    if verbose:\n  1062\t        for k in sorted(set(factors).difference(set(factors0))):\n  1063\t            print(factor_msg % (k, factors[k]))\n  1064\t    return int(n), len(factors) != nfactors\n  1065\t\n  1066\t\n  1067\tdef _check_termination(factors, n, limit, use_trial, use_rho, use_pm1,\n  1068\t                       verbose, next_p):\n  1069\t    \"\"\"\n  1070\t    Helper function for integer factorization. Checks if ``n``\n  1071\t    is a prime or a perfect power, and in those cases updates the factorization.\n  1072\t    \"\"\"\n  1073\t    if verbose:\n  1074\t        print('Check for termination')\n  1075\t    if n == 1:\n  1076\t        if verbose:\n  1077\t            print(complete_msg)\n  1078\t        return True\n  1079\t    if n < next_p**2 or isprime(n):\n  1080\t        factor_cache[n] = n\n  1081\t        factors[int(n)] = 1\n  1082\t        if verbose:\n  1083\t            print(complete_msg)\n  1084\t        return True\n  1085\t\n  1086\t    # since we've already been factoring there is no need to do\n  1087\t    # simultaneous factoring with the power check\n  1088\t    p = _perfect_power(n, next_p)\n  1089\t    if not p:\n  1090\t        return False\n  1091\t    base, exp = p\n  1092\t    if base < next_p**2 or isprime(base):\n  1093\t        factor_cache[n] = base\n  1094\t        factors[base] = exp\n  1095\t    else:\n  1096\t        facs = factorint(base, limit, use_trial, use_rho, use_pm1,\n  1097\t                         verbose=False)\n  1098\t        for b, e in facs.items():\n  1099\t            if verbose:\n  1100\t                print(factor_msg % (b, e))\n  1101\t            factors[b] = exp*e\n  1102\t    if verbose:\n  1103\t        print(complete_msg)\n  1104\t    return True\n  1105\t\n  1106\t\n  1107\ttrial_int_msg = \"Trial division with ints [%i ... %i] and fail_max=%i\"\n  1108\ttrial_msg = \"Trial division with primes [%i ... %i]\"\n  1109\trho_msg = \"Pollard's rho with retries %i, max_steps %i and seed %i\"\n  1110\tpm1_msg = \"Pollard's p-1 with smoothness bound %i and seed %i\"\n  1111\tecm_msg = \"Elliptic Curve with B1 bound %i, B2 bound %i, num_curves %i\"\n  1112\tfactor_msg = '\\t%i ** %i'\n  1113\tfermat_msg = 'Close factors satisying Fermat condition found.'\n  1114\tcomplete_msg = 'Factorization is complete.'\n  1115\t\n  1116\t\n  1117\tdef _factorint_small(factors, n, limit, fail_max, next_p=2):\n  1118\t    \"\"\"\n  1119\t    Return the value of n and either a 0 (indicating that factorization up\n  1120\t    to the limit was complete) or else the next near-prime that would have\n  1121\t    been tested.\n  1122\t\n  1123\t    Factoring stops if there are fail_max unsuccessful tests in a row.\n  1124\t\n  1125\t    If factors of n were found they will be in the factors dictionary as\n  1126\t    {factor: multiplicity} and the returned value of n will have had those\n  1127\t    factors removed. The factors dictionary is modified in-place.\n  1128\t\n  1129\t    \"\"\"\n  1130\t\n  1131\t    def done(n, d):\n  1132\t        \"\"\"return n, d if the sqrt(n) was not reached yet, else\n  1133\t           n, 0 indicating that factoring is done.\n  1134\t        \"\"\"\n  1135\t        if d*d <= n:\n  1136\t            return n, d\n  1137\t        return n, 0\n  1138\t\n  1139\t    limit2 = limit**2\n  1140\t    threshold2 = min(n, limit2)\n  1141\t\n  1142\t    if next_p < 3:\n  1143\t        if not n & 1:\n  1144\t            m = bit_scan1(n)\n  1145\t            factors[2] = m\n  1146\t            n >>= m\n  1147\t            threshold2 = min(n, limit2)\n  1148\t        next_p = 3\n  1149\t        if threshold2 < 9: # next_p**2 = 9\n  1150\t            return done(n, next_p)\n  1151\t\n  1152\t    if next_p < 5:\n  1153\t        if not n % 3:\n  1154\t            n //= 3\n  1155\t            m = 1\n  1156\t            while not n % 3:\n  1157\t                n //= 3\n  1158\t                m += 1\n  1159\t                if m == 20:\n  1160\t                    n, mm = remove(n, 3)\n  1161\t                    m += mm\n  1162\t                    break\n  1163\t            factors[3] = m\n  1164\t            threshold2 = min(n, limit2)\n  1165\t        next_p = 5\n  1166\t        if threshold2 < 25: # next_p**2 = 25\n  1167\t            return done(n, next_p)\n  1168\t\n  1169\t    # Because of the order of checks, starting from `min_p = 6k+5`,\n  1170\t    # useless checks are caused.\n  1171\t    # We want to calculate\n  1172\t    # next_p += [-1, -2, 3, 2, 1, 0][next_p % 6]\n  1173\t    p6 = next_p % 6\n  1174\t    next_p += (-1 if p6 < 2 else 5) - p6\n  1175\t\n  1176\t    fails = 0\n  1177\t    while fails < fail_max:\n  1178\t        # next_p % 6 == 5\n  1179\t        if n % next_p:\n  1180\t            fails += 1\n  1181\t        else:\n  1182\t            n //= next_p\n  1183\t            m = 1\n  1184\t            while not n % next_p:\n  1185\t                n //= next_p\n  1186\t                m += 1\n  1187\t                if m == 20:\n  1188\t                    n, mm = remove(n, next_p)\n  1189\t                    m += mm\n  1190\t                    break\n  1191\t            factors[next_p] = m\n  1192\t            fails = 0\n  1193\t            threshold2 = min(n, limit2)\n  1194\t        next_p += 2\n  1195\t        if threshold2 < next_p**2:\n  1196\t            return done(n, next_p)\n  1197\t\n  1198\t        # next_p % 6 == 1\n  1199\t        if n % next_p:\n  1200\t            fails += 1\n  1201\t        else:\n  1202\t            n //= next_p\n  1203\t            m = 1\n  1204\t            while not n % next_p:\n  1205\t                n //= next_p\n  1206\t                m += 1\n  1207\t                if m == 20:\n  1208\t                    n, mm = remove(n, next_p)\n  1209\t                    m += mm\n  1210\t                    break\n  1211\t            factors[next_p] = m\n  1212\t            fails = 0\n  1213\t            threshold2 = min(n, limit2)\n  1214\t        next_p += 4\n  1215\t        if threshold2 < next_p**2:\n  1216\t            return done(n, next_p)\n  1217\t    return done(n, next_p)\n  1218\t\n  1219\t\n  1220\tdef factorint(n, limit=None, use_trial=True, use_rho=True, use_pm1=True,\n  1221\t              use_ecm=True, verbose=False, visual=None, multiple=False):\n  1222\t    r\"\"\"\n  1223\t    Given a positive integer ``n``, ``factorint(n)`` returns a dict containing\n  1224\t    the prime factors of ``n`` as keys and their respective multiplicities\n  1225\t    as values. For example:\n","exit_code":0,"status":"completed"}}
